// ===========================================
// NODE 1: PARSE MESSAGES
// Parses Gmail and Facebook messages into unified format
// Detects media (audio, video, image) for Gemini processing
// ===========================================

const item = $json;

// Get the body (webhook format) or use item directly
const body = item.body || item;

// Default values
let sourceChannel = 'unknown';
let messageContent = '';
let customerEmail = '';
let customerName = '';
let senderId = '';
let subject = '';
let hasMedia = false;
let mediaType = 'text';
let mediaUrl = null;
let mediaAttachments = [];

// Reply IDs
let gmailMessageId = null;
let gmailThreadId = null;
let fbSenderId = null;

// ===========================================
// FACEBOOK FORMAT
// ===========================================
if (body.object === 'page' && body.entry) {
  sourceChannel = 'facebook';

  const entry = body.entry[0];
  const messaging = entry?.messaging?.[0];

  if (messaging) {
    senderId = messaging.sender?.id || '';
    messageContent = messaging.message?.text || '';
    customerEmail = senderId + '@facebook.com';
    customerName = 'Facebook User ' + senderId;

    // Capture Facebook sender ID for replies
    fbSenderId = senderId;

    // Check for media attachments
    const attachments = messaging.message?.attachments || [];
    if (attachments.length > 0) {
      hasMedia = true;

      for (const att of attachments) {
        const attType = att.type === 'fallback' ? 'file' : att.type;
        mediaAttachments.push({
          type: attType,
          url: att.payload?.url
        });
      }

      mediaType = mediaAttachments[0].type;
      mediaUrl = mediaAttachments[0].url;

      // If no text but has media, set placeholder
      if (!messageContent) {
        messageContent = '[Customer sent ' + mediaType + ']';
      }
    }
  }

// ===========================================
// GMAIL FORMAT
// ===========================================
} else if (body.threadId || body.labelIds) {
  sourceChannel = 'email';

  // Capture Gmail IDs for reply functionality
  gmailMessageId = body.id || '';
  gmailThreadId = body.threadId || '';

  // Get message content
  messageContent = body.snippet || body.text || body.body || '';

  // Try to decode base64 body
  if (body.payload?.body?.data) {
    try {
      const decoded = Buffer.from(body.payload.body.data, 'base64').toString('utf-8');
      messageContent = decoded.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() || messageContent;
    } catch (e) {}
  }

  // Try parts for multipart messages
  if (!messageContent && body.payload?.parts) {
    for (const part of body.payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        try {
          messageContent = Buffer.from(part.body.data, 'base64').toString('utf-8');
          break;
        } catch (e) {}
      }
    }
  }

  // Get headers
  const headers = body.payload?.headers || [];
  const fromHeader = headers.find(h => h.name?.toLowerCase() === 'from');
  const subjectHeader = headers.find(h => h.name?.toLowerCase() === 'subject');

  const fromField = fromHeader?.value || body.From || body.from || '';
  subject = subjectHeader?.value || body.Subject || body.subject || '';

  // Extract email and name
  const emailMatch = fromField.match(/<([^>]+)>/) || fromField.match(/([^\s]+@[^\s]+)/);
  customerEmail = emailMatch ? emailMatch[1] : fromField;

  const nameMatch = fromField.match(/^([^<]+)</);
  customerName = nameMatch ? nameMatch[1].trim().replace(/"/g, '') : customerEmail.split('@')[0];

  senderId = customerEmail;

  // Check for attachments
  if (body.payload?.parts) {
    for (const part of body.payload.parts) {
      if (part.filename && part.filename.length > 0) {
        const filename = part.filename.toLowerCase();
        let type = 'file';
        if (filename.match(/\.(jpg|jpeg|png|gif|webp|bmp|svg)$/i)) type = 'image';
        else if (filename.match(/\.(mp4|mov|avi|webm|mkv|flv|wmv|3gp)$/i)) type = 'video';
        else if (filename.match(/\.(mp3|wav|ogg|m4a|aac|wma|flac|opus|amr)$/i)) type = 'audio';

        mediaAttachments.push({
          type: type,
          filename: part.filename,
          mimeType: part.mimeType,
          attachmentId: part.body?.attachmentId
        });
      }
    }

    if (mediaAttachments.length > 0) {
      hasMedia = true;
      mediaType = mediaAttachments[0].type;
    }
  }

// ===========================================
// FALLBACK
// ===========================================
} else {
  messageContent = body.text || body.message || body.content || item.text || '';
  customerEmail = body.email || body.from || 'unknown@unknown.com';
  customerName = body.name || body.sender || 'Unknown';
  senderId = body.sender_id || body.senderId || customerEmail;
  sourceChannel = body.channel || body.source || 'webhook';
}

// Ensure string
messageContent = String(messageContent || '').trim();

// Generate ticket ID
const ticketId = 'TICKET-' + Date.now() + Math.random().toString(36).substring(2, 6).toUpperCase();

// Determine processing needs
const needsTranscription = hasMedia && (mediaType === 'audio' || mediaType === 'video');
const needsImageAnalysis = hasMedia && mediaType === 'image';

// ===========================================
// RETURN UNIFIED FORMAT
// ===========================================
return {
  json: {
    // Ticket info
    ticket_id: ticketId,
    timestamp: new Date().toISOString(),

    // Customer info
    customer_name: customerName,
    customer_email: customerEmail,
    sender_id: senderId,

    // Channel info
    source_channel: sourceChannel,
    subject: subject,

    // Reply IDs (for sending responses)
    gmail_message_id: gmailMessageId,
    gmail_thread_id: gmailThreadId,
    fb_sender_id: fbSenderId,

    // Message content
    original_text: messageContent,
    customer_text: messageContent,

    // Media info
    has_media: hasMedia,
    media_type: mediaType,
    media_url: mediaUrl,
    media_attachments: mediaAttachments,

    // Processing flags
    needs_transcription: needsTranscription,
    needs_image_analysis: needsImageAnalysis,

    // Will be filled later
    was_transcribed: false,
    transcription: null,

    // Raw data for debugging
    raw_data: item
  }
};

