// ===========================================
// NODE 8: ESCALATION CHECKER
// Analyzes text (including transcribed audio/video/image) for complaints
// Score >= 5 = Escalate to Slack
// ===========================================

const input = $json;
const text = (input.customer_text || '').toLowerCase();
const subject = (input.subject || '').toLowerCase();
const combinedText = text + ' ' + subject;

const hasMedia = input.has_media === true;
const mediaType = input.media_type || 'text';
const wasTranscribed = input.was_transcribed === true;

let score = 0;
let reasons = [];

// ===========================================
// LEGAL THREATS (+10) - ALWAYS ESCALATE
// ===========================================
if (combinedText.includes('sue')) { score += 10; reasons.push('⚖️ sue'); }
if (combinedText.includes('lawyer')) { score += 10; reasons.push('⚖️ lawyer'); }
if (combinedText.includes('attorney')) { score += 10; reasons.push('⚖️ attorney'); }
if (combinedText.includes('lawsuit')) { score += 10; reasons.push('⚖️ lawsuit'); }
if (combinedText.includes('legal action')) { score += 10; reasons.push('⚖️ legal action'); }
if (combinedText.includes('court')) { score += 5; reasons.push('⚖️ court'); }

// ===========================================
// OFFENSIVE (+5)
// ===========================================
if (combinedText.includes('scam')) { score += 5; reasons.push('🚨 scam'); }
if (combinedText.includes('fraud')) { score += 5; reasons.push('🚨 fraud'); }
if (combinedText.includes('fake')) { score += 5; reasons.push('🚨 fake'); }
if (combinedText.includes('stolen')) { score += 5; reasons.push('🚨 stolen'); }
if (combinedText.includes('counterfeit')) { score += 5; reasons.push('🚨 counterfeit'); }
if (combinedText.includes('rip off') || combinedText.includes('ripoff')) { score += 5; reasons.push('🚨 rip off'); }
if (combinedText.includes('chargeback')) { score += 5; reasons.push('💳 chargeback'); }
if (combinedText.includes('bbb') || combinedText.includes('better business bureau')) { score += 5; reasons.push('⚠️ BBB'); }
if (combinedText.includes('report you') || combinedText.includes('report this')) { score += 5; reasons.push('⚠️ report'); }

// ===========================================
// STRONG NEGATIVE (+4)
// ===========================================
if (combinedText.includes('worst')) { score += 4; reasons.push('😡 worst'); }
if (combinedText.includes('terrible')) { score += 4; reasons.push('😡 terrible'); }
if (combinedText.includes('horrible')) { score += 4; reasons.push('😡 horrible'); }
if (combinedText.includes('disgusting')) { score += 4; reasons.push('😡 disgusting'); }
if (combinedText.includes('unacceptable')) { score += 4; reasons.push('😡 unacceptable'); }
if (combinedText.includes('pathetic')) { score += 4; reasons.push('😡 pathetic'); }
if (combinedText.includes('hate')) { score += 4; reasons.push('😡 hate'); }
if (combinedText.includes('never again')) { score += 4; reasons.push('👋 never again'); }
if (combinedText.includes('waste of money')) { score += 4; reasons.push('💸 waste'); }
if (combinedText.includes('awful')) { score += 4; reasons.push('😡 awful'); }

// ===========================================
// ANGRY (+3)
// ===========================================
if (combinedText.includes('angry')) { score += 3; reasons.push('😠 angry'); }
if (combinedText.includes('furious')) { score += 3; reasons.push('😠 furious'); }
if (combinedText.includes('outraged')) { score += 3; reasons.push('😠 outraged'); }
if (combinedText.includes('pissed')) { score += 3; reasons.push('😠 pissed'); }
if (combinedText.includes('frustrated')) { score += 2; reasons.push('😤 frustrated'); }

// ===========================================
// BAD + REFUND COMBO (+5)
// ===========================================
const hasBadWord = combinedText.includes('bad') || combinedText.includes('poor');
const hasRefundWord = combinedText.includes('refund') || combinedText.includes('money back');

if (hasBadWord && hasRefundWord) {
  score += 5;
  reasons.push('💰 bad + refund');
}

// ===========================================
// MEDIA WITH ISSUE (+3)
// ===========================================
if (input.image_analysis?.issue && input.image_analysis.issue.toLowerCase() !== 'none') {
  score += 3;
  reasons.push('📷 image shows: ' + input.image_analysis.issue);
}

if (input.issue_from_media) {
  score += 3;
  reasons.push('🎥 media shows: ' + input.issue_from_media);
}

// ===========================================
// MEDIA + COMPLAINT BONUS (+2)
// ===========================================
if (hasMedia && wasTranscribed && score >= 3) {
  score += 2;
  const emoji = mediaType === 'audio' ? '🎤' : mediaType === 'video' ? '🎥' : '📷';
  reasons.push(`${emoji} ${mediaType} with complaint`);
}

// ===========================================
// ALL CAPS (+3)
// ===========================================
const originalText = input.customer_text || '';
if (originalText.length > 15 && originalText === originalText.toUpperCase()) {
  score += 3;
  reasons.push('🔊 ALL CAPS');
}

// ===========================================
// URGENCY WORDS (+1)
// ===========================================
if (combinedText.includes('immediately') || combinedText.includes('right now') || combinedText.includes('asap')) {
  score += 1;
  reasons.push('⏰ urgent');
}

// ===========================================
// DETERMINE ESCALATION
// ===========================================
const shouldEscalate = score >= 5;

let priority = 'low';
if (score >= 10) priority = 'critical';
else if (score >= 5) priority = 'high';
else if (score >= 3) priority = 'medium';

let sentiment = 'neutral';
if (score >= 4) sentiment = 'negative';
else if (/thank|thanks|great|awesome|love|excellent|perfect|amazing/i.test(combinedText) && score === 0) {
  sentiment = 'positive';
}

// ===========================================
// RETURN
// ===========================================
return {
  json: {
    ...input,
    sentiment: sentiment,
    shouldEscalate: shouldEscalate,
    escalationScore: score,
    priority: priority,
    escalationReasonText: reasons.length > 0 ? reasons.join('; ') : 'none',
    flags: {
      is_complaint: score >= 5,
      has_media: hasMedia,
      media_type: mediaType,
      was_transcribed: wasTranscribed,
      negative_sentiment: sentiment === 'negative'
    }
  }
};

// Process Gemini Response - COMPLETE

const geminiResponse = $json;

// Extract transcription
let transcribedText = '';
if (geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text) {
  transcribedText = geminiResponse.candidates[0].content.parts[0].text.trim();
}

// Extract order ID from transcription
let orderId = null;
const match = transcribedText.match(/UK-?\s*(\d{4,})/i);
if (match) {
  orderId = 'UK-' + match[1];
}

// Extract issue if mentioned
let issue = null;
if (/damage|broken|torn|defect/i.test(transcribedText)) issue = 'damaged';
else if (/wrong|incorrect/i.test(transcribedText)) issue = 'wrong_item';
else if (/missing|not included/i.test(transcribedText)) issue = 'missing';

// Get original data from If Has Media node
let originalData = {};
try {
  originalData = $('If Has Media').first().json || {};
} catch (e) {
  originalData = {};
}

return {
  json: {
    // Original customer info
    ticket_id: originalData.ticket_id || 'TICKET-' + Date.now(),
    timestamp: originalData.timestamp || new Date().toISOString(),
    customer_name: originalData.customer_name || 'Unknown',
    customer_email: originalData.customer_email || '',
    sender_id: originalData.sender_id || '',
    source_channel: originalData.source_channel || 'facebook',

    // Transcribed content - THIS IS THE KEY
    customer_text: transcribedText,
    transcription: transcribedText,
    original_text: originalData.original_text || '',

    // Extracted from transcription
    order_id: orderId,
    order_id_from_media: orderId,
    issue_from_media: issue,

    // Media flags
    has_media: true,
    media_type: originalData.media_type || 'audio',
    media_url: originalData.media_url || '',
    was_transcribed: true,
    transcription_source: 'gemini',

    // Pass through
    raw_data: originalData.raw_data
  }
};

// ===========================================
// NODE 7: EXTRACT INFO
// Extracts order ID, brand, size, color, issue, etc.
// Works with both transcribed and original text
// ===========================================

const item = $json;

// Get the text to analyze
const text = item.customer_text || item.transcription || item.original_text || '';
const subject = item.subject || '';
const combinedText = (text + ' ' + subject).trim();
const lowerText = combinedText.toLowerCase();

// ===========================================
// EXTRACT ORDER ID
// ===========================================
let orderId = item.order_id_from_media || null;

if (!orderId) {
  const orderPatterns = [
    /UK-\s*(\d{4,})/i,
    /UK\s*(\d{4,})/i,
    /order\s*#?\s*(\d{4,})/i,
    /order\s*number\s*[:\s]*(\d{4,})/i,
    /order\s+id[:\s]*([A-Z0-9-]+)/i,
    /#(\d{4,})/
  ];

  for (const pattern of orderPatterns) {
    const match = combinedText.match(pattern);
    if (match) {
      const num = match[1] || match[0];
      orderId = 'UK-' + num.replace(/\D/g, '');
      break;
    }
  }
}

// ===========================================
// EXTRACT TRACKING NUMBER
// ===========================================
let trackingNumber = null;
const trackingPatterns = [
  /1Z[A-Z0-9]{16}/i,  // UPS
  /\b\d{12,22}\b/,     // FedEx, USPS
  /tracking[:\s#]*([A-Z0-9]{10,})/i
];

for (const pattern of trackingPatterns) {
  const match = combinedText.match(pattern);
  if (match) {
    trackingNumber = (match[1] || match[0]).toUpperCase();
    break;
  }
}

// ===========================================
// EXTRACT BRAND
// ===========================================
const brands = {
  'Nike': /\bnike\b|air max|air force|dunk|blazer/i,
  'Jordan': /\bjordan\b|aj\d/i,
  'Adidas': /\badidas\b|yeezy|ultra boost|superstar/i,
  'Converse': /\bconverse\b|chuck taylor|chuck 70/i,
  'New Balance': /new balance|nb\s*\d{3,4}/i,
  'Vans': /\bvans\b|old skool/i,
  'Puma': /\bpuma\b/i,
  'Reebok': /\breebok\b/i
};

let brandMentioned = null;
for (const [brand, pattern] of Object.entries(brands)) {
  if (pattern.test(lowerText)) {
    brandMentioned = brand;
    break;
  }
}

// ===========================================
// EXTRACT PRODUCT
// ===========================================
const products = [
  { pattern: /air\s*max\s*97/i, name: 'Air Max 97', brand: 'Nike' },
  { pattern: /air\s*max\s*95/i, name: 'Air Max 95', brand: 'Nike' },
  { pattern: /air\s*max\s*90/i, name: 'Air Max 90', brand: 'Nike' },
  { pattern: /air\s*max\s*1\b/i, name: 'Air Max 1', brand: 'Nike' },
  { pattern: /air\s*force\s*1|af1/i, name: 'Air Force 1', brand: 'Nike' },
  { pattern: /dunk\s*(low|high)?/i, name: 'Dunk', brand: 'Nike' },
  { pattern: /blazer/i, name: 'Blazer', brand: 'Nike' },
  { pattern: /jordan\s*1|aj1/i, name: 'Jordan 1', brand: 'Jordan' },
  { pattern: /jordan\s*4/i, name: 'Jordan 4', brand: 'Jordan' },
  { pattern: /jordan\s*11/i, name: 'Jordan 11', brand: 'Jordan' },
  { pattern: /yeezy\s*350/i, name: 'Yeezy 350', brand: 'Adidas' },
  { pattern: /yeezy\s*500/i, name: 'Yeezy 500', brand: 'Adidas' },
  { pattern: /yeezy\s*700/i, name: 'Yeezy 700', brand: 'Adidas' },
  { pattern: /ultra\s*boost/i, name: 'Ultra Boost', brand: 'Adidas' },
  { pattern: /superstar/i, name: 'Superstar', brand: 'Adidas' },
  { pattern: /chuck\s*70/i, name: 'Chuck 70', brand: 'Converse' },
  { pattern: /chuck\s*taylor/i, name: 'Chuck Taylor', brand: 'Converse' },
  { pattern: /old\s*skool/i, name: 'Old Skool', brand: 'Vans' }
];

let productMentioned = null;
for (const product of products) {
  if (product.pattern.test(lowerText)) {
    productMentioned = product.name;
    if (!brandMentioned) brandMentioned = product.brand;
    break;
  }
}

// ===========================================
// EXTRACT SIZE
// ===========================================
let sizeMentioned = null;
let sizeType = 'US';

const sizePatterns = [
  { pattern: /\bus\s*(\d+\.?\d*)/i, type: 'US' },
  { pattern: /\buk\s*(\d+\.?\d*)/i, type: 'UK' },
  { pattern: /\beu\s*(\d+\.?\d*)/i, type: 'EU' },
  { pattern: /size\s*(\d+\.?\d*)/i, type: 'US' },
  { pattern: /(\d+\.?\d*)\s*(us|uk|eu)/i, type: null }
];

for (const sp of sizePatterns) {
  const match = combinedText.match(sp.pattern);
  if (match) {
    sizeMentioned = match[1];
    if (sp.type) {
      sizeType = sp.type;
    } else if (match[2]) {
      sizeType = match[2].toUpperCase();
    }
    break;
  }
}

// ===========================================
// EXTRACT COLOR
// ===========================================
const colors = [
  'black', 'white', 'red', 'blue', 'green', 'yellow', 'orange',
  'purple', 'pink', 'brown', 'grey', 'gray', 'navy', 'beige',
  'cream', 'gold', 'silver', 'bred', 'chicago', 'royal',
  'shadow', 'mocha', 'travis', 'panda', 'zebra', 'triple white'
];

let colorMentioned = null;
for (const color of colors) {
  if (lowerText.includes(color)) {
    colorMentioned = color;
    break;
  }
}

// ===========================================
// DETECT ISSUE TYPE
// ===========================================
let issueType = item.issue_from_media || null;

if (!issueType) {
  const issues = {
    'damaged': /damaged|broken|torn|ripped|crushed|cracked|scratched/i,
    'wrong_item': /wrong (item|product|shoe|order|color|model)|received.*(wrong|different)|not what i ordered/i,
    'wrong_size': /wrong size|size.*(wrong|incorrect)|too (big|small|tight|loose)/i,
    'missing': /missing|not included|didn't receive|never got|incomplete/i,
    'defective': /defective|defect|faulty|not working|manufacturing/i,
    'late': /late|delayed|still waiting|taking too long|slow/i,
    'not_delivered': /not delivered|never arrived|didn't arrive|lost/i,
    'fake': /fake|counterfeit|not authentic|not real|replica/i,
    'quality': /quality|cheap|poor quality|bad quality/i
  };

  for (const [issue, pattern] of Object.entries(issues)) {
    if (pattern.test(lowerText)) {
      issueType = issue;
      break;
    }
  }
}

// ===========================================
// DETECT ACTION REQUESTED
// ===========================================
const actions = {
  'refund': /refund|money back|get my money/i,
  'exchange': /exchange|swap|replace|replacement|new one/i,
  'return': /return|send back|send it back/i,
  'cancel': /cancel|cancellation/i,
  'track': /track|where is|where's|status|update/i,
  'expedite': /faster|rush|expedite|asap|urgent/i,
  'complaint': /complain|complaint|report/i
};

let actionRequested = null;
for (const [action, pattern] of Object.entries(actions)) {
  if (pattern.test(lowerText)) {
    actionRequested = action;
    break;
  }
}

// ===========================================
// DETECT MESSAGE INTENT
// ===========================================
let messageIntent = 'general_inquiry';

if (orderId || /where.*(order|package|delivery)|track|status|shipping|delivered/i.test(lowerText)) {
  messageIntent = 'order_inquiry';
} else if (/size|sizing|fit|measurement|width|length/i.test(lowerText)) {
  messageIntent = 'sizing_question';
} else if (/policy|return|refund|exchange|shipping time|payment|discount|promo/i.test(lowerText)) {
  messageIntent = 'faq_question';
} else if (/stock|available|availability|price|cost|how much/i.test(lowerText)) {
  messageIntent = 'product_inquiry';
} else if (issueType) {
  messageIntent = 'issue_report';
} else if (/thank|thanks|great|awesome|love|excellent|perfect|amazing/i.test(lowerText)) {
  messageIntent = 'positive_feedback';
}

